/* 
 * Minimal ECharts Stub
 * This file is not a full ECharts implementation, but rather a stub that provides
 * just enough functionality for our fallback mechanism to work if all CDN sources fail
 */
(function() {
    window.echarts = {
        init: function() {
            console.error('使用的是ECharts存根，不是完整的ECharts库');
            return {
                setOption: function() {},
                resize: function() {},
                dispose: function() {}
            };
        },
        version: '5.4.3-stub',
        connect: function() {},
        disconnect: function() {},
        dispose: function() {},
        getInstanceByDom: function() { return null; },
        registerMap: function() {},
        getMap: function() { return {}; },
        registerTheme: function() {}
    };
    
    // 自动触发降级显示
    setTimeout(function() {
        if (window.renderCharts && typeof window.renderCharts.fallback === 'function') {
            console.warn('使用ECharts存根，触发降级显示');
            window.renderCharts.fallback();
        }
    }, 500);
})(); 